import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

export async function runMotionOrbitBloomDepthSmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()})),dir=await fs.mkdtemp(path.join(os.tmpdir(),'nagweb-bloom-depth-')),colors=[[255,0,0],[0,255,0],[0,0,255],[255,255,0]],files=[];let revision=0;
 for(let i=0;i<4;i++){const file=path.join(dir,'Petalo-'+i+'.svg');await fs.writeFile(file,'<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200"><rect width="200" height="200" fill="rgb('+colors[i].join(',')+')"/></svg>');files.push(file);}
 async function ready(count){await page.waitForFunction(count=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelectorAll('.nw-bloom-card').length===count&&d.defaultView.__NAG_SCROLL_DIRECTOR?.[d.querySelector('.sc')?.dataset.id]&&Array.from(d.querySelectorAll('[data-nw-stream-slot] img')).every(n=>n.complete&&n.naturalWidth>0);},{},count);}
 async function change(selector,value){const mark='bloom-depth-'+(++revision);await page.$eval(selector,(n,{value,mark})=>{document.querySelector('.nw-motion-dialog iframe').contentDocument.body.dataset.depthOld=mark;if(n.type==='checkbox')n.checked=value;else n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},{value,mark});await page.waitForFunction(mark=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.body&&d.body.dataset.depthOld!==mark&&d.querySelector('.nw-bloom-card');},{},mark);await ready(4);}
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});const before=await page.evaluate(()=>JSON.stringify(project));await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="orbit-bloom"]');await ready(12);await change('[data-motion-stream-count]','4');await (await page.$('[data-motion-stream-batch-upload]')).uploadFile(...files);await page.waitForFunction(()=>/Se cargaron/.test(document.querySelector('[data-motion-stream-batch-status]').textContent));await ready(4);await change('[data-motion-stream="cardSize"]','70');await change('[data-motion-stream="lean"]','55');await change('[data-motion-stream="cornerRadius"]','0');await change('[data-motion-stream="backFade"]','0');await change('[data-motion-stream="shadow"]',false);
  for(const curve of ['75','-75']){
   await change('[data-motion-stream="curve"]',curve);let probe=null;
   for(const progress of [.07,.13,.23,.37,.53,.71,.89]){
    probe=await page.$eval('.nw-motion-dialog iframe',(f,progress)=>{const d=f.contentDocument;f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id].set(progress);const nodes=Array.from(d.querySelectorAll('[data-nw-stream-slot]')),canvas=d.querySelector('.nw-bloom-surface'),host=canvas.offsetParent,scale=canvas.width/host.clientWidth,strips=nodes.flatMap((n,slot)=>(n.__nwMotionStrips||[]).map(s=>({...s,id:n.dataset.id,slot,rank:+n.style.zIndex})));function inside(poly,x,y){let hit=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a.y>y)!==(b.y>y)&&x<(b.x-a.x)*(y-a.y)/(b.y-a.y)+a.x)hit=!hit;}return hit;}
     for(const candidate of strips){const center=candidate.polygon.reduce((p,v)=>({x:p.x+v.x/4,y:p.y+v.y/4}),{x:0,y:0}),px=Math.floor(center.x*scale),py=Math.floor(center.y*scale),x=(px+.5)/scale,y=(py+.5)/scale;if(x<3||x>host.clientWidth-3||y<3||y>host.clientHeight-3)continue;const hits=strips.filter(s=>inside(s.polygon,x,y)).sort((a,b)=>b.depth-a.depth);if(new Set(hits.map(n=>n.id)).size<2)continue;const top=hits[0];if(![[.6,0],[-.6,0],[0,.6],[0,-.6]].every(([dx,dy])=>inside(top.polygon,x+dx,y+dy)))continue;const pixel=Array.from(canvas.getContext('2d').getImageData(px,py,1,1).data),fr=f.getBoundingClientRect(),hr=host.getBoundingClientRect();return{id:top.id,slot:top.slot,pixel,x:fr.left+(hr.left+x)*fr.width/f.clientWidth,y:fr.top+(hr.top+y)*fr.height/f.clientHeight};}return null;},progress);if(probe)break;
   }
   assert.ok(probe,'Curved petals have a visible overlap to verify depth');assert.equal(probe.pixel[3],255);for(let i=0;i<3;i++)assert.ok(Math.abs(probe.pixel[i]-colors[probe.slot][i])<5,JSON.stringify(probe));await page.mouse.click(probe.x,probe.y);await page.waitForFunction(id=>document.querySelector('[data-motion-layer="'+id+'"]')?.getAttribute('aria-pressed')==='true',{},probe.id);
  }
  assert.equal(await page.evaluate(()=>JSON.stringify(project)),before);await page.click('[data-motion-insert-group]');const gid=await page.evaluate(()=>sec().elements.find(e=>e.nwMotionInstance).id);await page.evaluate(()=>{const f=document.createElement('iframe');f.id='bloom-depth-export';f.style.cssText='width:1280px;height:720px';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>{const f=document.querySelector('#bloom-depth-export'),d=f?.contentDocument;return f?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid]&&d?.querySelector('.nw-bloom-surface')&&Array.from(d.querySelectorAll('[data-nw-stream-slot] img')).every(n=>n.complete&&n.naturalWidth===200);},{},gid);const rendered=await page.$eval('#bloom-depth-export',(f,gid)=>{f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].set(.13);const c=f.contentDocument.querySelector('.nw-bloom-surface'),bytes=c.getContext('2d').getImageData(0,0,c.width,c.height).data;let opaque=0;for(let i=3;i<bytes.length;i+=4)if(bytes[i]===255)opaque++;return opaque;},gid);assert.ok(rendered>1000,'Curved petals are drawn in the standalone HTML too');await page.evaluate(()=>document.querySelector('#bloom-depth-export').remove());console.log('Orbit Bloom curvo: píxeles reales en cruces de pétalos, orden global de superficies y selección de la imagen visible con curvatura positiva/negativa, borrador sin escrituras y HTML curvo independiente OK');
 }catch(error){await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await page.screenshot({path:'/tmp/nagweb-motion-visuals/orbit-bloom-depth-failure.png'}).catch(()=>{});throw error;}finally{await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#bloom-depth-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);await fs.rm(dir,{recursive:true,force:true});}
}
